'use strict';
// A tableside reference for ranked combat. Dice are entered by the player.
(function(root,factory){
  const api=factory(root);
  if(typeof module==='object'&&module.exports)module.exports=api;
  if(root)root.TOWCombatCharts=api;
})(typeof window==='undefined'?null:window,function(root){
  const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const lang=()=>root?.TOWI18n?.language||'ko';
  const tr=(ko,en)=>lang()==='en'?en:lang()==='both'?ko+' / '+en:ko;
  const t=(ko,en)=>esc(tr(ko,en));
  const named=(ko,en)=>lang()==='en'?esc(en):esc(ko)+'<small class="combatOriginal">'+esc(en)+'</small>';
  const draft={leadership:'',defeatMargin:'',die1:'',die2:'',outnumbered:'unknown'};
  const rankTypes=[
    ['레귤러 인팬트리','Regular Infantry',5,2],['헤비 인팬트리','Heavy Infantry',4,2],
    ['몬스트러스 인팬트리','Monstrous Infantry',3,2],['라이트 캐벌리','Light Cavalry',5,1],
    ['헤비 캐벌리','Heavy Cavalry',4,1],['몬스트러스 캐벌리','Monstrous Cavalry',3,1],
    ['워 비스트','War Beasts',5,1],['라이트 채리엇','Light Chariots',3,1]
  ];
  const scores=[
    ['입힌 상처','Wounds inflicted','+1 / W','사망 모델 수가 아니라 막지 못한 W. 이번 턴 Stand & Shoot 상처와 리제너레이션으로 회복한 W도 셉니다.','Count unsaved Wounds, not slain models. Include this turn’s Stand & Shoot wounds and Wounds recovered by Regeneration.'],
    ['랭크 보너스','Rank bonus','+1 / rank','첫 랭크 뒤의 유효 랭크. 병종별 상한 적용. 다중 전투는 같은 편에서 가장 높은 하나만 셉니다.','Eligible ranks behind the first, capped by troop type. Multiple combat uses only the highest Rank Bonus on the side.'],
    ['스탠다드','Standard','+1','한 전투에서 같은 편의 일반 깃발 보너스는 하나만 셉니다.','Only one ordinary standard bonus per side in a combat.'],
    ['배틀 스탠다드','Battle Standard','+1','일반 스탠다드와 별도로 하나를 더 셀 수 있습니다.','One Battle Standard bonus may be added separately from the ordinary standard.'],
    ['측면 / 후면','Flank / Rear','+1 / +2','적 유닛마다 각 항목 한 번. 같은 적 양쪽 측면을 공격해도 측면은 +1이며, 측면과 후면은 함께 셉니다.','Once per enemy unit for each category. Both flanks of the same enemy still give only +1; flank and rear bonuses combine.'],
    ['고지','High ground','+1','전투 랭크의 높이를 비교합니다. 다중 전투는 각 편에서 가장 높은 전투 랭크로 비교합니다.','Compare fighting-rank heights; in multiple combat use the highest fighting rank on each side.'],
    ['클로즈 오더의 전투 대형','Close Order in Combat Order','+1','Close Order·Combat Order·US 10 이상을 모두 충족한 유닛마다 +1. 랭크 보너스와 별개입니다.','+1 per unit with Close Order, in Combat Order, with Unit Strength 10 or more. Separate from Rank Bonus.'],
    ['매스트 인팬트리','Massed Infantry','+1','이 규칙이 있는 유닛을 포함하며, 전투에 참가한 자기 편 US 합이 상대보다 클 때 자기 편에 한 번만 적용합니다.','Once per side containing this rule, if that side’s total Unit Strength in the combat is greater than the enemy’s.'],
    ['챌린지 오버킬','Challenge overkill','+1 / W · max +5','챌린지 상대의 남은 W를 초과한 미저장 W당 +1, 챌린지당 최대 +5. 실제 W와 초과 W를 중복 계산하지 않습니다.','+1 per excess unsaved Wound beyond a challenge opponent’s remaining Wounds, max +5 per challenge. Do not count the same Wound twice.'],
    ['그 밖의 효과','Other effects','—','마법 깃발·특수 규칙 등에 적힌 추가 점수와 중복 제한을 적용합니다.','Apply additional scores and stacking restrictions specified by magic standards and special rules.']
  ];
  function matches(query=''){
    const terms='방진 충돌 랭크 대열 rank formation combat result 전투 결과 승패 점수 깃발 스탠다드 패주 도주 브레이크 break flee fallback fall back good order fbigo give ground 기브 그라운드 리더십 leadership ld 2d6 주사위 판정표 chart unit strength us 수적 우세 압도';
    return String(query).trim().toLowerCase().split(/\s+/).filter(Boolean).every(token=>terms.includes(token)||terms.replace(/\s/g,'').includes(token));
  }
  function table(caption,headers,rows,cls=''){
    return '<div class="combatTableScroll" role="region" tabindex="0" aria-label="'+esc(caption)+'"><table class="combatTable '+cls+'"><caption>'+esc(caption)+'</caption><thead><tr>'+headers.map(h=>'<th scope="col">'+h+'</th>').join('')+'</tr></thead><tbody>'+rows.map(row=>'<tr>'+row.map((cell,i)=>i?'<td>'+cell+'</td>':'<th scope="row">'+cell+'</th>').join('')+'</tr>').join('')+'</tbody></table></div>';
  }
  function rankTable(){return table(tr('병종별 기본 랭크 기준','Basic Rank Bonus by troop type'),[t('병종','Troop type'),t('유효 랭크 최소 모델','Models per eligible rank'),t('기본 최대 보너스','Basic maximum bonus')],rankTypes.map(([ko,en,width,cap])=>[named(ko,en),String(width),'+'+cap]),'combatRankTable');}
  function scoreTable(){return table(tr('전투 결과 점수표','Combat result scores'),[t('항목','Item'),t('점수','Score'),t('적용 조건','Conditions')],scores.map(([ko,en,points,note,enNote])=>[named(ko,en),esc(points),t(note,enNote)]));}
  function breakTable(){return table(tr('일반 브레이크 테스트: 위에서부터 확인','Ordinary Break test: check from the top'),[t('조건','Condition'),t('결과','Result')],[
    [t('① 주사위가 자연 더블 1','① Natural double 1'),named('기브 그라운드 · 밀려남','Give Ground')],
    [t('② 자연 합 > Ld','② Natural total > Ld'),named('브레이크 앤 플리 · 패주','Break & Flee')],
    [t('③ 자연 합 ≤ Ld, 수정 합 > Ld','③ Natural total ≤ Ld, modified total > Ld'),named('폴 백 인 굿 오더 · 질서 있는 후퇴','Fall Back in Good Order (FBIGO)')],
    [t('④ 수정 합 ≤ Ld','④ Modified total ≤ Ld'),named('기브 그라운드 · 밀려남','Give Ground')]
  ]);}
  function regiment(rows,label){return '<figure class="combatRegiment"><div class="combatRanks" aria-hidden="true">'+Array.from({length:rows},(_,rank)=>'<div class="'+(rank?'':'front')+'">'+Array.from({length:5},()=>'<i></i>').join('')+'</div>').join('')+'</div><figcaption>'+esc(label)+'</figcaption></figure>';}
  function calculator(){
    const field=(name,ko,en,min,max)=>'<div class="combatField"><label for="combat-'+name+'">'+t(ko,en)+'</label><input id="combat-'+name+'" data-combat-field="'+name+'" type="number" inputmode="numeric" step="1" min="'+min+'" max="'+max+'" value="'+esc(draft[name])+'" autocomplete="off"></div>';
    return '<details class="combatCalculator"><summary>'+t('브레이크 판정 도우미','Break-test helper')+'</summary><div class="combatCalculatorBody"><p>'+t('일반 브레이크 테스트용입니다. 스터번·언브레이커블·실드월 등의 특수 규칙은 자동 적용하지 않습니다. 재굴림을 했다면 최종으로 채택한 주사위 두 개를 입력하세요.','For an ordinary Break test. Stubborn, Unbreakable, Shieldwall and other overrides are not applied automatically. After a re-roll, enter the two dice you must accept.')+'</p><div class="combatFields">'+field('leadership','패배 유닛 Ld','Losing unit’s Ld',1,10)+field('defeatMargin','패배 점수 차 (+)','Losing margin (+)',1,999)+field('die1','첫 번째 D6','First D6',1,6)+field('die2','두 번째 D6','Second D6',1,6)+'<div class="combatField combatUSField"><label for="combat-outnumbered">'+t('승리 측 US가 패배 측 US의 2배를 초과하나요?','Is the winning side’s US more than twice the losing side’s?')+'</label><select id="combat-outnumbered" data-combat-field="outnumbered">'+[['unknown','아직 비교하지 않음','Not checked yet'],['no','아니요 · 정확히 2배도 포함','No · includes exactly twice'],['yes','예 · 2배 초과','Yes · more than twice']].map(([value,ko,en])=>'<option value="'+value+'"'+(draft.outnumbered===value?' selected':'')+'>'+t(ko,en)+'</option>').join('')+'</select></div></div><p class="combatHelperNote">'+t('US는 모델 수가 아니라 Unit Strength입니다. 다중 전투는 전투 종료 시 참가한 각 편의 전체 US를 비교합니다.','US means Unit Strength, not model count. In multiple combat compare each side’s total US at the end of combat.')+'</p><div id="combat-break-result" class="combatBreakResult" role="status" aria-live="polite" aria-atomic="true"></div><button type="button" class="secondary" data-combat-reset>'+t('입력 초기화','Reset inputs')+'</button></div></details>';
  }
  function html(query=''){
    if(!matches(query))return '';
    return '<article class="quickCard combatResultChart" id="combat-result-chart"><header class="quickCardHead"><div><span class="quickPage">'+t('랭크 → 전투 결과 → 브레이크','Ranks → Combat result → Break test')+'</span><h3>'+t('방진 전투의 승패·패주 판정','Ranked combat: victory and breaking')+'</h3></div><button type="button" class="secondary" data-quick-handbook="battle-result-score">'+t('상세 설명','Full explanation')+'</button></header><p class="combatLead">'+t('모든 공격과 사상자 제거를 마친 뒤, 양측의 상처·랭크·깃발·위치 보너스를 합합니다. 패배한 각 유닛이 브레이크 테스트를 해서 밀려남·질서 있는 후퇴·패주를 정합니다.','After all attacks and casualty removal, add each side’s wounds, ranks, standards and position bonuses. Each losing unit takes its own Break test to determine Give Ground, Fall Back in Good Order or Break & Flee.')+'</p><ol class="combatFlow"><li>'+t('1. 살아남은 대형에서 랭크 계산','1. Count surviving eligible ranks')+'</li><li>'+t('2. 점수 합산·패배 차 계산','2. Total scores and losing margin')+'</li><li>'+t('3. 2D6·Ld·US 비교','3. Compare 2D6, Ld and US')+'</li></ol><div class="combatTables"><section><h4>'+t('① 랭크 보너스부터 확인','① Find the Rank Bonus')+'</h4><p>'+t('첫 랭크는 제외하고 뒤쪽 유효 랭크마다 +1입니다. Close Order 또는 Open Order의 Combat Order(가로 모델 수가 세로 모델 수 이상)에서 병종별 최소 폭과 상한을 적용합니다.','Exclude the first rank and add +1 for each eligible rank behind it. Use the troop-type width and cap while in Close Order or Open Order Combat Order: at least as many models across as deep.')+'</p>'+rankTable()+'<ul class="combatNotes"><li>'+t('불완전한 마지막 랭크도 최소 모델 수를 채우면 셉니다. Horde는 실제 랭크를 추가하지 않고 보너스 상한을 +1합니다.','An incomplete last rank counts if it meets the minimum width. Horde raises the bonus cap by 1; it does not create a real rank.')+'</li><li>'+t('Swarms·Heavy Chariots·Monstrous Creatures·Behemoths·War Machines의 기본 랭크 보너스는 없습니다.','Swarms, Heavy Chariots, Monstrous Creatures, Behemoths and War Machines have no basic Rank Bonus.')+'</li><li>'+t('Disrupted면 랭크 보너스 0. 적 US 5 이상이 측후면에 교전하면 적용되지만, 적 Skirmishers는 이 방식으로 대형을 붕괴시키지 않습니다. 이동 종료 시 모델의 25% 이상이 험지에 있거나 낮은 선형 장애물에 걸친 경우도 적용합니다.','Disrupted units have no Rank Bonus. An enemy with US 5 or more in the flank or rear causes Disruption, except enemy Skirmishers do not do so. Disruption also applies when ending movement with at least 25% of models in difficult terrain or straddling a low linear obstacle.')+'</li><li>'+t('헤비 인팬트리의 Steady in the Ranks: Close Order 또는 Open Order일 때 측후면 교란은 적 US 10 이상에서 적용됩니다. 지형·장애물에 의한 교란은 별개입니다.','Heavy Infantry with Steady in the Ranks: in Close Order or Open Order, flank or rear Disruption requires enemy US 10 or more. Terrain and obstacle Disruption still apply separately.')+'</li></ul><button type="button" class="secondary" data-quick-handbook="battle-rank-score">'+t('랭크·다중 전투 상세','Ranks and multiple combats')+'</button></section><section><h4>'+t('② 양측 전투 결과 합산','② Total each side’s combat result')+'</h4>'+scoreTable()+'<p class="combatCallout">'+t('높은 점수가 승리합니다. 패배 차 = 승자 점수 − 패자 점수이며, 이 양수를 브레이크 주사위 합에 더합니다.','The higher score wins. Losing margin = winner’s score − loser’s score. Add that positive margin to the Break-test dice total.')+'</p><p>'+t('동점이면 먼저 뮤지션을 확인합니다. 한쪽만 전방 랭크에 뮤지션이 있으면 그쪽에 +1. 양쪽 모두 있거나 모두 없으면 무승부로 교전을 유지하며 일반 브레이크 테스트를 하지 않습니다.','On a tie check musicians first: only one side having a musician in a front rank gives that side +1. Both or neither means a draw; remain engaged without an ordinary Break test.')+'</p></section></div><section class="combatBreakSection"><h4>'+t('③ 패배한 각 유닛의 브레이크 테스트','③ Each losing unit takes its Break test')+'</h4><p class="combatFormula">'+t('자연 합 = D6 + D6 · 수정 합 = 자연 합 + 패배 점수 차','Natural total = D6 + D6 · Modified total = natural total + losing margin')+'</p>'+breakTable()+'<p class="combatCallout">'+t('승리 측 US가 패배 측 US의 2배를 초과하면 FBIGO만 Break & Flee로 바뀝니다. 정확히 2배는 해당하지 않으며, Give Ground와 자연 더블 1은 패주로 바뀌지 않습니다.','If the winning side’s US is more than twice the losing side’s, only FBIGO becomes Break & Flee. Exactly twice does not qualify. Give Ground and natural double 1 do not become a break.')+'</p><p>'+t('밀려남은 기본 2″ 후퇴이며 공간 제한을 적용합니다. FBIGO는 도주처럼 이동하되 기본 2D6 중 낮은 주사위를 버리고, 이동 끝에 자동 재집결합니다. 패주는 도주·추격 규칙을 적용합니다.','Give Ground normally moves 2″, subject to space restrictions. FBIGO moves as fleeing, normally rolling 2D6 and discarding the lower die, then automatically rallies at the end. Break & Flee follows fleeing and pursuit rules.')+'</p>'+calculator()+'<details class="combatOverrides"><summary>'+t('특수 규칙·리더십·재굴림 예외','Special rules, Leadership and re-rolls')+'</summary><ul class="combatNotes"><li>'+t('허용되는 유닛 내 최고 Ld 또는 사용 가능한 장군 Ld를 사용합니다. Inspiring Presence·커맨드 범위·도주 상태의 제한을 적용하세요.','Use the highest permitted Ld in the unit or an eligible General’s Ld. Apply Inspiring Presence, Command range and fleeing restrictions.')+'</li><li>'+t('Stubborn: 처음 요구되는 브레이크 테스트에 주사위 대신 자동 FBIGO를 선택할 수 있으며, 적 US가 2배를 초과해도 가능합니다. 사용 자격과 일회성 여부를 확인하세요.','Stubborn: the first required Break test may instead be an automatic FBIGO, even against more than twice the US. Check eligibility and whether it has been used.')+'</li><li>'+t('Unbreakable: 패배하면 브레이크 주사위 없이 자동 Give Ground입니다. Unstable 등 다른 군세 규칙도 별도로 적용합니다.','Unbreakable: automatically Give Ground after losing without rolling a Break test. Apply Unstable and other army rules separately.')+'</li><li>'+t('Shieldwall: 게임당 한 번, 돌격받은 턴에 Close Order 유닛이 방패를 장비하고 사용한다면 FBIGO 대신 Give Ground를 선택할 수 있습니다. 일반 패주 결과를 모두 바꾸는 규칙이 아닙니다.','Shieldwall: once per game, in a turn it was charged, a Close Order unit equipped with and using shields may Give Ground instead of FBIGO. It does not replace every Break & Flee result.')+'</li><li>'+t('도주 중이 아닌 BSB의 커맨드 범위 안에서 적용하는 Hold Your Ground는 실패한 경우에만이 아니라 브레이크 테스트 2D6를 재굴림할 수 있게 합니다. 두 번째 결과는 더 나빠도 받아들입니다.','An eligible BSB’s Hold Your Ground may re-roll the Break test, not only a failed result. Accept the second result even if worse.')+'</li></ul></details></section><section class="combatWorked"><h4>'+t('예시: 5×3 방진과 5×2 방진','Example: 5×3 versus 5×2')+'</h4><p>'+t('공격 후 남은 레귤러 인팬트리 A 15명·B 10명입니다. 양쪽 모두 Close Order·Combat Order·스탠다드·Massed Infantry가 있고, 별도 브레이크 대체 규칙은 없습니다. 그 밖의 보너스는 없다고 가정합니다.','After attacks, A has 15 and B has 10 Regular Infantry. Both have Close Order, Combat Order, a standard and Massed Infantry, with no rule replacing the ordinary Break test. Assume no other bonuses.')+'</p><div class="combatWorkedSides">'+regiment(3,tr('A · 15모델 · 랭크 +2','A · 15 models · ranks +2'))+regiment(2,tr('B · 10모델 · 랭크 +1','B · 10 models · ranks +1'))+'</div><p>'+t('A: 입힌 상처 3 + 랭크 2 + 깃발 1 + Close Order 1 + Massed Infantry 1 = 8점. B: 입힌 상처 1 + 랭크 1 + 깃발 1 + Close Order 1 = 4점. 따라서 B가 4점 차로 패배합니다.','A: 3 wounds + 2 ranks + 1 standard + 1 Close Order + 1 Massed Infantry = 8. B: 1 wound + 1 rank + 1 standard + 1 Close Order = 4. B loses by 4.')+'</p><p>'+t('B의 Ld 8, 주사위 3+4라면 자연 합 7 ≤ 8, 수정 합 7+4=11 > 8이므로 FBIGO입니다. A의 US 15는 B의 US 10의 2배를 초과하지 않아 패주로 바뀌지 않습니다.','With B at Ld 8 and dice 3+4, natural 7 ≤ 8 but modified 7+4=11 > 8, so B falls back in good order. A’s US 15 is not more than twice B’s 10, so it does not become a break.')+'</p></section><footer class="combatSources">'+t('원문·정오표 대조: 2026-11-04','Rules and errata checked: 2026-11-04')+' · '+[['랭크 기준','Troop type table','/troop-types-at-a-glance/troop-type-table'],['점수표','Combat scores','/the-combat-phase/combat-result-table'],['브레이크','Break tests','/the-combat-phase/break-test'],['정오표','Errata','/errata']].map(([ko,en,path])=>'<a href="https://tow.whfb.app'+path+'" target="_blank" rel="noopener noreferrer">'+t(ko,en)+' ↗</a>').join(' · ')+'</footer></article>';
  }
  function resultHTML(result){
    if(!result||result.kind==='incomplete')return '<p>'+t('Ld·패배 점수 차·주사위 두 개를 입력하면 기본 결과를 확인합니다.','Enter Ld, losing margin and both dice to see the ordinary result.')+'</p>';
    if(result.kind==='invalid')return '<p>'+t('Ld 1–10, 양의 패배 차 1–999, 각 D6 1–6의 정수를 입력하세요.','Enter integers: Ld 1–10, positive losing margin 1–999 and each D6 1–6.')+'</p>';
    const kinds={'give-ground':['밀려남 · Give Ground','Give Ground'],'fall-back':['질서 있는 후퇴 · FBIGO','Fall Back in Good Order'],'break':['패주 · Break & Flee','Break & Flee'],'check-unit-strength':['US 비교 후 결과 확정','Check Unit Strength before confirming']};
    const reasons={'double-one':['자연 더블 1이므로 다른 보정과 무관하게 Give Ground입니다.','Natural double 1 gives Give Ground regardless of modifiers.'],'natural-failure':['자연 합이 Ld보다 높으므로 패주합니다.','The natural total exceeds Ld: the unit breaks and flees.'],'modified-pass':['수정 합이 Ld 이하이므로 Give Ground입니다.','The modified total is at or below Ld: Give Ground.'],'outnumbered':['기본 결과는 FBIGO지만 승리 측 US가 2배를 초과해 패주로 바뀝니다.','The ordinary result is FBIGO, converted to Break & Flee by more than twice the US.'],'modified-failure':['자연 합은 Ld 이하, 수정 합은 Ld 초과이며 압도적 US 조건이 없어 FBIGO입니다.','Natural total is at or below Ld, modified total exceeds it, and the US conversion does not apply: FBIGO.'],'unit-strength-unknown':['기본 결과는 FBIGO입니다. 승리 측 US가 2배를 초과하면 패주로 바뀌므로 US 비교를 선택하세요.','The ordinary result is FBIGO. It becomes a break if the winning side has more than twice the US; select the US comparison.']};
    const heading=kinds[result.kind]||['결과 확인','Check result'],reason=reasons[result.reason];
    return '<strong>'+t(...heading)+'</strong><p>'+t('자연 합','Natural total')+' '+esc(result.natural)+' · '+t('수정 합','Modified total')+' '+esc(result.natural)+' + '+esc(result.margin)+' = '+esc(result.modified)+' · Ld '+esc(result.leadership)+'</p>'+(reason?'<p>'+t(...reason)+'</p>':'');
  }
  function mount(host){
    if(!host)return;
    const update=()=>{const output=host.querySelector('#combat-break-result');if(!output)return;const result=root?.TOWCombatResultCore?.resolveBreak(draft);output.innerHTML=resultHTML(result);};
    if(!host.dataset.combatMounted){
      host.dataset.combatMounted='true';
      const input=event=>{const field=event.target.dataset.combatField;if(!Object.hasOwn(draft,field))return;draft[field]=event.target.value;update();};
      host.addEventListener('input',input);host.addEventListener('change',input);
      host.addEventListener('click',event=>{if(!event.target.closest('[data-combat-reset]'))return;for(const key of Object.keys(draft))draft[key]=key==='outnumbered'?'unknown':'';for(const field of host.querySelectorAll('[data-combat-field]'))field.value=draft[field.dataset.combatField];update();});
    }
    update();
  }
  return {html,matches,mount,resultHTML,rankTable,scoreTable,breakTable};
});
